51	import org.springframework.samples.petclinic.util.OwnerIdentity;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.context.request.RequestAttributes;
57	import org.springframework.web.context.request.RequestContextHolder;
58	import org.springframework.web.context.request.ServletRequestAttributes;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic email validation: a non-empty local part, a single '@', and a
74	     * domain with at least one dot-separated label ending in a letter-only TLD.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
78	
79	    /**
80	     * Disposable / throw-away email domains whose owners are rejected: an email on one of these
81	     * domains is treated as invalid input and rejected with 400. Compared case-insensitively.
82	     */
83	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
84	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
85	
86	    /**
87	     * Fixed public-holiday list. A registration date that lands on one of these is not a business
88	     * day and is rolled forward to the next non-holiday weekday.
89	     */
90	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS =
91	        java.util.Set.of(
92	            LocalDate.of(2026, 1, 1),
93	            LocalDate.of(2026, 1, 26),
94	            LocalDate.of(2026, 4, 25),
95	            LocalDate.of(2026, 12, 25),
96	            LocalDate.of(2026, 12, 28));
97	
98	    /** Dedicated audit logger for owner lifecycle side-effects. */
99	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
100	
101	    /** Request header carrying the client-supplied idempotency key for owner creation. */
102	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
103	
104	    /**
105	     * Remembers which owner was created for each already-seen idempotency key, so a repeated create
106	     * carrying a key seen before returns the originally created owner instead of creating a duplicate.
107	     */
108	    private final Map<String, Integer> idempotentCreations = new ConcurrentHashMap<>();
109	
110	    private final ClinicService clinicService;
111	
112	    private final OwnerMapper ownerMapper;
113	
114	    private final PetMapper petMapper;
115	
116	    private final VisitMapper visitMapper;
117	
118	    public OwnerRestControllerV1(ClinicService clinicService,
119	                                 OwnerMapper ownerMapper,
120	                                 PetMapper petMapper,
121	                                 VisitMapper visitMapper) {
122	        this.clinicService = clinicService;
123	        this.ownerMapper = ownerMapper;
124	        this.petMapper = petMapper;
125	        this.visitMapper = visitMapper;
126	    }
127	
128	    /**
129	     * Normalise a raw telephone number to E.164 form.
130	     *
131	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
132	     * code are kept when present; otherwise country code '+61' is assumed and a
133	     * single leading '0' is dropped from the national digits. The result must have
134	     * between 8 and 15 digits after the '+'.
135	     *
136	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
137	     * national-number length is additionally validated against that country code:
138	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
139	     * length is wrong for its country is rejected.
140	     *
141	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
142	     */
143	    static String toE164(String raw) {
144	        if (raw == null) {
145	            return null;
146	        }
147	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
148	        String digits;
149	        boolean explicitCountryCode;
150	        if (cleaned.startsWith("+")) {
151	            digits = cleaned.substring(1);
152	            explicitCountryCode = true;
153	        } else {
154	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
155	            digits = "61" + national;
156	            explicitCountryCode = false;
157	        }
158	        if (!digits.matches("[0-9]{8,15}")) {
159	            return null;
160	        }
161	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
162	            return null;
163	        }
164	        return "+" + digits;
165	    }
166	
167	    /**
168	     * Validate the national-number length of an E.164 number (its digits without the
169	     * leading '+') against the requirement for its country code: country code '+61'
170	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
171	     * without a configured length requirement are accepted unchanged.
172	     */
173	    private static boolean hasValidNationalLength(String digits) {
174	        if (digits.startsWith("61")) {
175	            return digits.length() - "61".length() == 9;
176	        }
177	        if (digits.startsWith("1")) {
178	            return digits.length() - "1".length() == 10;
179	        }
180	        return true;
181	    }
182	
183	    /**
184	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
185	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
186	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
187	     * input normalises to the empty string.
188	     */
189	    private static String normaliseIdentity(String value) {
190	        if (value == null) {
191	            return "";
192	        }
193	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
194	    }
195	
196	    /**
197	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
198	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
199	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
200	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
201	     * that is both stored and used for every address comparison.
202	     */
203	    static String normaliseAddress(String value) {
204	        if (value == null) {
205	            return "";
206	        }
207	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
208	        if (collapsed.isEmpty()) {
209	            return "";
210	        }
211	        String[] tokens = collapsed.split(" ");
212	        StringBuilder result = new StringBuilder();
213	        for (int i = 0; i < tokens.length; i++) {
214	            if (i > 0) {
215	                result.append(' ');
216	            }
217	            result.append(expandAddressAbbreviation(tokens[i]));
218	        }
219	        return result.toString();
220	    }
221	
222	    /**
223	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
224	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
225	     * returned unchanged.
226	     */
227	    private static String expandAddressAbbreviation(String token) {
228	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
229	        return switch (core) {
230	            case "ST" -> "STREET";
231	            case "RD" -> "ROAD";
232	            case "AVE" -> "AVENUE";
233	            default -> token;
234	        };
235	    }
236	
237	    /**
238	     * Derive the stable, shared household identifier for owners in the same household: the first 12
239	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
240	     * so every owner with the same last name and postcode resolves to the same value regardless of
241	     * the order in which they were created.
242	     */
243	    private static String householdId(String lastNameKey, String postcode) {
244	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
245	    }
246	
247	    /**
248	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
249	     * name and postcode). An owner without a postcode has no household peers and counts as a household
250	     * of one.
251	     */
252	    private int householdSize(Owner owner) {
253	        if (owner.getPostcode() == null) {
254	            return 1;
255	        }
256	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
257	        return (int) this.clinicService.findAllOwners().stream()
258	            .filter(existing -> existing.getPostcode() != null
259	                && householdId.equals(
260	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
261	            .count();
262	    }
263	
264	    /**
265	     * The existing, non-deleted owners that belong to {@code owner}'s household (sharing its
266	     * normalized last name and postcode), excluding {@code owner} itself. An owner without a
267	     * postcode has no household peers, so this is empty.
268	     */
269	    private List<Owner> otherHouseholdMembers(Owner owner) {
270	        if (owner.getPostcode() == null) {
271	            return List.of();
272	        }
273	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
274	        return this.clinicService.findAllOwners().stream()
275	            .filter(existing -> !existing.isDeleted())
276	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
277	            .filter(existing -> existing.getPostcode() != null
278	                && householdId.equals(
279	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
280	            .toList();
281	    }
282	
283	    /**
284	     * The owner's membership level after applying the household ceiling: the natural level derived
285	     * from the owner's membership points, capped at one above the current maximum membership level
286	     * among the owner's existing household members. With no existing household member no cap applies.
287	     * Assumes the owner's household size has already been populated.
288	     */
289	    private Integer cappedMembershipLevel(Owner owner) {
290	        Integer natural = ownerMapper.formatMembershipLevel(owner);
291	        if (natural == null) {
292	            return null;
293	        }
294	        List<Owner> members = otherHouseholdMembers(owner);
295	        if (members.isEmpty()) {
296	            return natural;
297	        }
298	        int maxMemberLevel = 0;
299	        for (Owner member : members) {
300	            member.setHouseholdSize(householdSize(member));
301	            Integer memberLevel = ownerMapper.formatMembershipLevel(member);
302	            if (memberLevel != null) {
303	                maxMemberLevel = Math.max(maxMemberLevel, memberLevel);
304	            }
305	        }
306	        return Math.min(natural, maxMemberLevel + 1);
307	    }
308	
309	    /**
310	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
311	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
312	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
313	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
314	     * only on the owner's own region and identity, not on how many owners already exist.
315	     */
316	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
317	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
318	    }
319	
320	    /**
321	     * De-duplicate a computed customer code against the codes already assigned to existing owners:
322	     * when {@code code} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
323	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
324	     */
325	    private String deduplicateCustomerCode(String code) {
326	        Set<String> existing = this.clinicService.findAllOwners().stream()
327	            .map(Owner::getCustomerCode)
328	            .filter(Objects::nonNull)
329	            .collect(Collectors.toSet());
330	        if (!existing.contains(code)) {
331	            return code;
332	        }
333	        int n = 2;
334	        while (existing.contains(code + "-" + n)) {
335	            n++;
336	        }
337	        return code + "-" + n;
338	    }
339	
340	    /**
341	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
342	     */
343	    private static String hash8(String input) {
344	        return hashHex(input, 8, true);
345	    }
346	
347	    /**
348	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
349	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
350	     */
351	    private static String hashHex(String input, int length, boolean upperCase) {
352	        try {
353	            byte[] digest = MessageDigest.getInstance("SHA-256")
354	                .digest(input.getBytes(StandardCharsets.UTF_8));
355	            StringBuilder sb = new StringBuilder(digest.length * 2);
356	            for (byte b : digest) {
357	                sb.append(String.format("%02x", b));
358	            }
359	            String hex = sb.substring(0, length);
360	            return upperCase ? hex.toUpperCase() : hex;
361	        }
362	        catch (java.security.NoSuchAlgorithmException e) {
363	            throw new IllegalStateException(e);
364	        }
365	    }
366	
367	    /**
368	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
369	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
370	     * fixed city-to-region table, else {@code "UNKNOWN"}.
371	     */
372	    private static String region(String postcode, String city) {
373	        String fromPostcode = regionForPostcode(postcode);
374	        return fromPostcode != null ? fromPostcode : regionForCity(city);
375	    }
376	
377	    /**
378	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
379	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
380	     */
381	    private static String regionForPostcode(String postcode) {
382	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
383	            return null;
384	        }
385	        int value = Integer.parseInt(postcode);
386	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
387	            int[] range = entry.getValue();
388	            if (value >= range[0] && value <= range[1]) {
389	                return entry.getKey();
390	            }
391	        }
392	        return null;
393	    }
394	
395	    /**
396	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
397	     * Sunday, or on a listed public holiday, it is advanced day by day to the next non-holiday
398	     * weekday; ordinary weekday dates are returned unchanged.
399	     */
400	    static LocalDate toBusinessDay(LocalDate date) {
401	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
402	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
403	            || PUBLIC_HOLIDAYS.contains(date)) {
404	            date = date.plusDays(1);
405	        }
406	        return date;
407	    }
408	
409	    /**
410	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
411	     * using the same per-day accumulation path as the daily create-limit rule.
412	     */
413	    private long ownersCreatedOn(LocalDate registrationDate) {
414	        LocalDate day = toBusinessDay(registrationDate);
415	        return this.clinicService.findAllOwners().stream()
416	            .map(Owner::getRegistrationDate)
417	            .filter(existing -> existing != null)
418	            .map(OwnerRestControllerV1::toBusinessDay)
419	            .filter(day::equals)
420	            .count();
421	    }
422	
423	    /**
424	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
425	     * postcode against the owner's city region.
426	     */
427	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
428	        "NSW", new int[] {2000, 2099},
429	        "VIC", new int[] {3000, 3099},
430	        "QLD", new int[] {4000, 4099});
431	
432	    /**
433	     * Resolve an owner's region from the city using the fixed city-to-region table
434	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
435	     * when the city is not listed.
436	     */
437	    private static String regionForCity(String city) {
438	        return switch (city == null ? "" : city) {
439	            case "Sydney" -> "NSW";
440	            case "Melbourne" -> "VIC";
441	            case "Brisbane" -> "QLD";
442	            default -> "UNKNOWN";
443	        };
444	    }
445	
446	    /**
447	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
448	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
449	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
450	     */
451	    private static boolean isPostcodeValid(String postcode, String city) {
452	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
453	            return false;
454	        }
455	        int[] range = REGION_POSTCODES.get(regionForCity(city));
456	        if (range == null) {
457	            return true;
458	        }
459	        int value = Integer.parseInt(postcode);
460	        return value >= range[0] && value <= range[1];
461	    }
462	
463	    /**
464	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
465	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
466	     */
467	    private static boolean isDisposableEmailDomain(String email) {
468	        if (email == null) {
469	            return false;
470	        }
471	        int at = email.lastIndexOf('@');
472	        if (at < 0 || at == email.length() - 1) {
473	            return false;
474	        }
475	        String domain = email.substring(at + 1).toLowerCase();
476	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
477	    }
478	
479	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
480	    @Override
481	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
482	        Collection<Owner> owners;
483	        if (lastName != null) {
484	            owners = this.clinicService.findOwnerByLastName(lastName);
485	        } else {
486	            owners = this.clinicService.findAllOwners();
487	        }
488	        if (owners.isEmpty()) {
489	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
490	        }
491	        owners.forEach(owner -> owner.setHouseholdSize(householdSize(owner)));
492	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
493	    }
494	
495	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
496	    @Override
497	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
498	        Owner owner = this.clinicService.findOwnerById(ownerId);
499	        if (owner == null) {
500	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
501	        }
502	        owner.setHouseholdSize(householdSize(owner));
503	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
504	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
505	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
506	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
507	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
508	    }
509	
510	    /**
511	     * The value of the {@code Idempotency-Key} header on the current request, or {@code null} when the
512	     * request carries no such header (or there is no active servlet request). A blank value is treated
513	     * as absent.
514	     */
515	    private static String currentIdempotencyKey() {
516	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
517	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
518	            return null;
519	        }
520	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
521	        return (key == null || key.isBlank()) ? null : key;
522	    }
523	
524	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
525	    @Override
526	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
527	        String idempotencyKey = currentIdempotencyKey();
528	        if (idempotencyKey != null) {
529	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
530	            if (existingId != null) {
531	                Owner existing = this.clinicService.findOwnerById(existingId);
532	                if (existing != null) {
533	                    existing.setHouseholdSize(householdSize(existing));
534	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
535	                    existingDto.setMembershipLevel(cappedMembershipLevel(existing));
536	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
537	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
538	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
539	                }
540	            }
541	        }
542	        String telephone = toE164(ownerFieldsDto.getTelephone());
543	        if (telephone == null) {
544	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
545	        }
546	        String email = ownerFieldsDto.getEmail();
547	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
548	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
549	        }
550	        if (isDisposableEmailDomain(email)) {
551	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
552	        }
553	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
554	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
555	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
556	        // normalized addressLine2 appended after a single space when present.
557	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
558	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
559	        boolean structuredAddress = !addressLine1.isEmpty();
560	        String address;
561	        if (structuredAddress) {
562	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
563	        } else {
564	            address = normaliseAddress(ownerFieldsDto.getAddress());
565	        }
566	        if (address.isEmpty()) {
567	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
568	        }
569	        String postcode = ownerFieldsDto.getPostcode();
570	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
571	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
572	        }
573	        if (ownerFieldsDto.getRegistrationDate() != null
574	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
575	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
576	        }
577	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
578	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
579	        LocalDate registrationDate = toBusinessDay(effectiveDate);
580	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
581	            .map(Owner::getRegistrationDate)
582	            .filter(existing -> existing != null)
583	            .map(OwnerRestControllerV1::toBusinessDay)
584	            .filter(registrationDate::equals)
585	            .count();
586	        if (ownersCreatedThatDay >= 100) {
587	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
588	        }
589	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
590	        long ownersInCity = this.clinicService.findAllOwners().stream()
591	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
592	            .count();
593	        if (ownersInCity >= 50) {
594	            return new ResponseEntity<>(HttpStatus.CONFLICT);
595	        }
596	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
597	        // The household is deterministically keyed on (normalized last name, postcode): every owner
598	        // with a postcode belongs to the household identified by this computed id, and owners sharing
599	        // a last name and postcode share it automatically. A new owner may join an existing household;
600	        // the household ceiling below (rather than a hard rejection) governs its membership level.
601	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
602	        // Duplicate detection is the single identity key (normalized telephone, lower-cased email and
603	        // Soundex of the last name). A candidate whose key collides with an existing, non-deleted
604	        // owner is a hard duplicate (409); the household id no longer participates in this decision.
605	        String identityKey = OwnerIdentity.identityKey(telephone, email, ownerFieldsDto.getLastName());
606	        boolean identityInUse = this.clinicService.findAllOwners().stream()
607	            .filter(existing -> !existing.isDeleted())
608	            .anyMatch(existing -> OwnerIdentity.identityKey(toE164(existing.getTelephone()),
609	                existing.getEmail(), existing.getLastName()).equals(identityKey));
610	        if (identityInUse) {
611	            return new ResponseEntity<>(HttpStatus.CONFLICT);
612	        }
613	        // Soft match: an existing, non-deleted owner sharing this owner's postcode and last-name
614	        // Soundex but with a different identity key (e.g. a different telephone) is not a hard
615	        // duplicate, but the new owner is flagged as a possible duplicate of it.
616	        String lastNameSoundex = OwnerIdentity.soundex(ownerFieldsDto.getLastName());
617	        Integer possibleDuplicateOf = (postcode == null) ? null
618	            : this.clinicService.findAllOwners().stream()
619	                .filter(existing -> !existing.isDeleted())
620	                .filter(existing -> postcode.equals(existing.getPostcode()))
621	                .filter(existing -> lastNameSoundex.equals(OwnerIdentity.soundex(existing.getLastName())))
622	                .filter(existing -> !OwnerIdentity.identityKey(toE164(existing.getTelephone()),
623	                    existing.getEmail(), existing.getLastName()).equals(identityKey))
624	                .map(Owner::getId)
625	                .findFirst()
626	                .orElse(null);
627	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
628	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
629	            .filter(existing ->
630	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
631	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
632	            .count();
633	        HttpHeaders headers = new HttpHeaders();
634	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
635	        owner.setNamesakeCount(namesakeCount);
636	        owner.setAddress(address);
637	        if (structuredAddress) {
638	            owner.setAddressLine1(addressLine1);
639	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
640	        } else {
641	            owner.setAddressLine1(null);
642	            owner.setAddressLine2(null);
643	        }
644	        owner.setTelephone(telephone);
645	        owner.setEmail(email == null ? null : email.toLowerCase());
646	        owner.setRegistrationDate(registrationDate);
647	        owner.setCustomerCode(deduplicateCustomerCode(nextCustomerCode(
648	            region(postcode, owner.getCity()), telephone, owner.getLastName())));
649	        owner.setHouseholdId(householdId);
650	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
651	        this.clinicService.saveOwner(owner);
652	        if (idempotencyKey != null) {
653	            this.idempotentCreations.put(idempotencyKey, owner.getId());
654	        }
655	        owner.setHouseholdSize(householdSize(owner));
656	        Integer membershipLevel = cappedMembershipLevel(owner);
657	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
658	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
659	            membershipLevel, ownerMapper.formatMembershipNumber(owner));
660	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
661	        ownerDto.setMembershipLevel(membershipLevel);
662	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
663	        headers.setLocation(UriComponentsBuilder.newInstance()
664	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
665	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
666	    }
667	
668	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
669	    @Override
670	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
671	        String telephone = toE164(ownerFieldsDto.getTelephone());
672	        if (telephone == null) {
673	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
674	        }
675	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
676	        if (currentOwner == null) {
677	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
678	        }
679	        String email = ownerFieldsDto.getEmail();
680	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
681	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
682	        }
683	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
684	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
685	        if (!addressLine1.isEmpty()) {
686	            currentOwner.setAddressLine1(addressLine1);
687	            currentOwner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
688	            currentOwner.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
689	        } else {
690	            currentOwner.setAddressLine1(null);
691	            currentOwner.setAddressLine2(null);
692	            currentOwner.setAddress(normaliseAddress(ownerFieldsDto.getAddress()));
693	        }
694	        currentOwner.setCity(ownerFieldsDto.getCity());
695	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
696	        currentOwner.setLastName(ownerFieldsDto.getLastName());
697	        currentOwner.setTelephone(telephone);
698	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
699	        this.clinicService.saveOwner(currentOwner);
700	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
701	    }
702	
703	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
704	    @Transactional
705	    @Override
706	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
707	        Owner owner = this.clinicService.findOwnerById(ownerId);
708	        if (owner == null) {
709	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
710	        }
711	        // Soft delete: flag the owner deleted and retain the record so it can still be read back.
712	        owner.setDeleted(true);
713	        this.clinicService.saveOwner(owner);
714	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
715	    }
716	
717	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
718	    @Override
719	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
720	        Owner owner = this.clinicService.findOwnerById(ownerId);
721	        if (owner == null) {
722	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
723	        }
