725	        Pet pet = petMapper.toPet(petFieldsDto);
726	        owner.setId(ownerId);
727	        pet.setOwner(owner);
728	        pet.getType().setName(null);
729	        this.clinicService.savePet(pet);
730	        PetDto petDto = petMapper.toPetDto(pet);
731	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
732	            .buildAndExpand(pet.getId()).toUri());
733	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
734	    }
735	
736	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
737	    @Override
738	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
739	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
740	        if (currentOwner != null) {
