769	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
770	    @Override
771	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
772	        Owner owner = this.clinicService.findOwnerById(ownerId);
773	        if (owner != null) {
